for (const auto& neighbor_pair : current_node->neighbors) {
    Node* neighbor = neighbor_pair.first;
    double edge_cost = neighbor_pair.second;
    if (neighbor->visited) continue;

    double new_g = current_node->g + edge_cost;
    if (new_g < neighbor->g) {
        neighbor->g = new_g;
        neighbor->h = std::sqrt(std::pow(neighbor->x - end_node->x, 2) + std::pow(neighbor->y - end_node->y, 2));
        neighbor->f = neighbor->g + neighbor->h;
        neighbor->parent = current_node;
        open_list.push_back(neighbor);
    }
}

